// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, type(uint256).max / 2);
        vm.deal(address(c), amount);
        vm.prank(address(this)); // setUp's msg.sender is the __owner
        c.sudicideAnyone();
        // Rule: after an owner-triggered sudicideAnyone, the contract is either
        // destroyed (empty code, reachable when balance is 0) or its whole
        // balance has been sent out to the caller (balance == 0).
        assertTrue(address(c).code.length == 0 || address(c).balance == 0);
    }
}
